use std::sync::{Arc, Mutex};
use std::collections::HashMap;
use std::time::{Duration, Instant};

#[derive(Clone, Debug)]
pub struct OAuthConfig {
    pub client_id: String,
    pub client_secret: String,
    pub allowed_redirect_uris: Vec<String>,
    pub token_endpoint: String,
}

#[derive(Clone, Debug, PartialEq)]
pub enum CircuitState {
    Closed,
    Open,
    HalfOpen,
}

#[derive(Clone, Debug)]
pub struct CircuitBreaker {
    state: CircuitState,
    failure_count: u32,
    threshold: u32,
    last_failure: Option<Instant>,
    recovery_timeout: Duration,
}

impl CircuitBreaker {
    pub fn new(threshold: u32, recovery_timeout: Duration) -> Self {
        Self {
            state: CircuitState::Closed,
            failure_count: 0,
            threshold,
            last_failure: None,
            recovery_timeout,
        }
    }

    pub fn record_failure(&mut self) {
        self.failure_count += 1;
        self.last_failure = Some(Instant::now());
        if self.failure_count >= self.threshold {
            self.state = CircuitState::Open;
        }
    }

    pub fn record_success(&mut self) {
        self.failure_count = 0;
        self.state = CircuitState::Closed;
    }

    pub fn can_execute(&mut self) -> bool {
        match self.state {
            CircuitState::Closed => true,
            CircuitState::Open => {
                if let Some(last) = self.last_failure {
                    if last.elapsed() > self.recovery_timeout {
                        self.state = CircuitState::HalfOpen;
                        true
                    } else {
                        false
                    }
                } else {
                    false
                }
            }
            CircuitState::HalfOpen => true,
        }
    }
}

#[derive(Clone, Debug)]
pub struct RedirectValidationResult {
    pub is_valid: bool,
    pub normalized_uri: String,
    pub match_type: MatchType,
}

#[derive(Clone, Debug)]
pub enum MatchType {
    Exact,
    None,
}

pub struct OAuthWorker {
    config: OAuthConfig,
    circuit_breaker: Arc<Mutex<CircuitBreaker>>,
    pending_jobs: Arc<Mutex<Vec<OAuthJob>>>,
}

#[derive(Clone, Debug)]
pub struct OAuthJob {
    pub job_id: String,
    pub redirect_uri: String,
    pub authorization_code: String,
    pub state_param: String,
}

impl OAuthWorker {
    pub fn new(config: OAuthConfig) -> Self {
        Self {
            config,
            circuit_breaker: Arc::new(Mutex::new(CircuitBreaker::new(5, Duration::from_secs(30)))),
            pending_jobs: Arc::new(Mutex::new(Vec::new())),
        }
    }

    fn normalize_uri(&self, uri: &str) -> String {
        let trimmed = uri.trim();
        let without_trailing = trimmed.trim_end_matches('/');
        let lowered_scheme = if without_trailing.starts_with("HTTPS://") || without_trailing.starts_with("Https://") {
            format!("https://{}", &without_trailing[8..])
        } else if without_trailing.starts_with("HTTP://") || without_trailing.starts_with("Http://") {
            format!("http://{}", &without_trailing[7..])
        } else {
            without_trailing.to_string()
        };
        lowered_scheme
    }

    pub fn validate_redirect_uri(&self, requested_uri: &str) -> RedirectValidationResult {
        let normalized_requested = self.normalize_uri(requested_uri);

        for allowed in &self.config.allowed_redirect_uris {
            let normalized_allowed = self.normalize_uri(allowed);

            if normalized_requested == normalized_allowed {
                return RedirectValidationResult {
                    is_valid: true,
                    normalized_uri: normalized_requested,
                    match_type: MatchType::Exact,
                };
            }
        }

        RedirectValidationResult {
            is_valid: false,
            normalized_uri: normalized_requested,
            match_type: MatchType::None,
        }
    }

    pub fn enqueue_job(&self, job: OAuthJob) -> Result<String, String> {
        let validation = self.validate_redirect_uri(&job.redirect_uri);
        if !validation.is_valid {
            return Err(format!("Invalid redirect URI: {}", job.redirect_uri));
        }

        let mut cb = self.circuit_breaker.lock().unwrap();
        if !cb.can_execute() {
            return Err("Circuit breaker is open, try again later".to_string());
        }
        drop(cb);

        let job_id = job.job_id.clone();
        let mut jobs = self.pending_jobs.lock().unwrap();
        jobs.push(job);
        Ok(job_id)
    }

    pub fn process_next_job(&self) -> Result<String, String> {
        let mut jobs = self.pending_jobs.lock().unwrap();
        if jobs.is_empty() {
            return Err("No pending jobs".to_string());
        }
        let job = jobs.remove(0);
        drop(jobs);

        let mut cb = self.circuit_breaker.lock().unwrap();
        if !cb.can_execute() {
            let mut jobs = self.pending_jobs.lock().unwrap();
            jobs.insert(0, job);
            return Err("Circuit breaker open".to_string());
        }
        drop(cb);

        match self.execute_token_exchange(&job) {
            Ok(token) => {
                let mut cb = self.circuit_breaker.lock().unwrap();
                cb.record_success();
                Ok(token)
            }
            Err(e) => {
                let mut cb = self.circuit_breaker.lock().unwrap();
                cb.record_failure();
                Err(e)
            }
        }
    }

    fn execute_token_exchange(&self, job: &OAuthJob) -> Result<String, String> {
        Ok(format!("token_for_{}", job.job_id))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn make_worker() -> OAuthWorker {
        let config = OAuthConfig {
            client_id: "test_client".to_string(),
            client_secret: "secret".to_string(),
            allowed_redirect_uris: vec![
                "https://app.example.com/callback".to_string(),
                "https://app.example.com/oauth/done".to_string(),
            ],
            token_endpoint: "https://auth.example.com/token".to_string(),
        };
        OAuthWorker::new(config)
    }

    #[test]
    fn test_exact_match_valid() {
        let worker = make_worker();
        let result = worker.validate_redirect_uri("https://app.example.com/callback");
        assert!(result.is_valid);
    }

    #[test]
    fn test_different_host_rejected() {
        let worker = make_worker();
        let result = worker.validate_redirect_uri("https://evil.com/callback");
        assert!(!result.is_valid);
    }

    #[test]
    fn test_subpath_rejected() {
        let worker = make_worker();
        let result = worker.validate_redirect_uri("https://app.example.com/callback/extra");
        assert!(!result.is_valid);
    }
}
